// Manual commission deductions use settlement snapshots so the same advance is never deducted twice.
let advanceContext=null;
function initAdvances(){state.advances??=[];for(const r of Object.values(state.records)){if(r.commissionPaid&&!r.settlement)r.settlement={gross:cents(r.commission),deductions:[],net:cents(r.commission),date:null};}}
function advanceUsed(id){return Object.values(state.records).reduce((sum,r)=>sum+(r.settlement?.deductions||[]).filter(d=>d.id===id).reduce((n,d)=>n+d.amount,0),0);}
function commissionSummary(person=selected,month=$('#month').value){initAdvances();const r=state.records[month+':'+person],gross=cents(r?.commission||0);if(r?.settlement){const s=r.settlement;return {...s,discount:s.deductions.reduce((n,d)=>n+d.amount,0),paid:s.net,remaining:0,closed:true};}return {gross,deductions:[],discount:0,net:gross,paid:0,remaining:gross,closed:false};}
function selectedAdvanceDeductions(gross){let total=0;const deductions=[];for(const checkbox of document.querySelectorAll('[data-advance-deduction]')){if(!checkbox.checked)continue;const id=checkbox.dataset.advanceDeduction,a=state.advances.find(a=>a.id===id),input=document.querySelector('[data-advance-amount="'+id+'"]'),remaining=a?Math.max(0,a.amount-advanceUsed(a.id)):0,amount=input?parseCredit(input.value):0;if(!a||a.voided||amount<=0||amount>remaining){toast('Confira o valor informado para o vale selecionado.');return null;}total+=amount;deductions.push({id:a.id,amount,description:a.description});}if(total>gross){toast('Os descontos não podem ultrapassar o valor da comissão.');return null;}return deductions;}
function settleCommission(){const r=record(),s=commissionSummary();if(s.closed){const later=Object.entries(state.records).some(([key,value])=>key.endsWith(':'+selected)&&key.slice(0,7)>$('#month').value&&value.settlement);if(later){toast('Reabra primeiro as comissões posteriores desta pessoa.');return;}if(!confirm('Reabrir esta comissão? O pagamento será desmarcado e os descontos voltarão aos vales.'))return;delete r.settlement;r.commissionPaid=false;}else{if(!s.gross)return;const deductions=selectedAdvanceDeductions(s.gross);if(!deductions)return;const discount=deductions.reduce((n,d)=>n+d.amount,0),net=s.gross-discount;if(!confirm('Confirmar quitação: comissão '+money(s.gross/100)+', descontos '+money(discount/100)+' e pagamento líquido de '+money(net/100)+'?'))return;r.settlement={gross:s.gross,deductions,net,date:new Intl.DateTimeFormat('sv-SE',{timeZone:'America/Sao_Paulo',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date())};r.commissionPaid=true;}save();render();}
function commissionPanel(){const s=commissionSummary(),open=state.advances.filter(a=>a.person===selected&&!a.voided&&a.amount>advanceUsed(a.id)).sort((a,b)=>a.date.localeCompare(b.date)||a.id.localeCompare(b.id));return `<div class="commission-breakdown"><div><small>Comissão bruta</small><strong>${money(s.gross/100)}</strong></div><div><small>Vales descontados</small><strong>− ${money(s.discount/100)}</strong></div><div><small>Líquido a receber</small><strong>${money(s.net/100)}</strong></div><div><small>Já pago em comissão</small><strong>${money(s.paid/100)}</strong></div></div>${!s.closed&&open.length?`<section class="advance-deduction-picker"><h3>Descontar vales nesta comissão</h3><p class="hint">Marque o vale e informe quanto deseja descontar agora.</p>${open.map(a=>{const remaining=a.amount-advanceUsed(a.id);return `<label class="advance-deduction-row"><input type="checkbox" data-advance-deduction="${esc(a.id)}"><span><strong>${esc(a.description)}</strong><small>Saldo do vale: ${money(remaining/100)}</small></span><input type="text" inputmode="decimal" data-money data-money-min="0.01" data-money-max="${remaining/100}" data-advance-amount="${esc(a.id)}" value="${formatCredit(remaining)}" aria-label="Valor a descontar de ${esc(a.description)}"></label>`;}).join('')}</section>`:''}<div class="week-top">${s.closed?'<p class="hint">Comissão quitada. Descontos e pagamento registrados.</p>':''}<button class="pay ${s.closed?'paid':''}" id="commission-pay" ${!s.gross?'disabled':''}>${s.closed?'✓ Quitada · reabrir':'Confirmar quitação da comissão'}</button></div>${s.deductions.length?`<details><summary>Ver descontos desta comissão</summary><dl class="ledger">${s.deductions.map(d=>`<div><dt>${esc(d.description)}</dt><dd>${money(d.amount/100)}</dd></div>`).join('')}</dl></details>`:''}`;}
function advancesView(){initAdvances();const list=state.advances.filter(a=>a.person===selected).sort((a,b)=>b.date.localeCompare(a.date));const outstanding=list.filter(a=>!a.voided).reduce((n,a)=>n+Math.max(0,a.amount-advanceUsed(a.id)),0);return `<div class="section-head" style="padding:0"><div><h3>Vales e adiantamentos</h3><p class="hint">Celular, aluguel, empréstimos e outros valores a descontar manualmente na comissão.</p></div><button class="primary" id="add-advance">＋ Registrar vale</button></div><div class="balance-summary"><div>Saldo total de vales a descontar<strong>${money(outstanding/100)}</strong></div></div><p class="hint">Na hora de quitar uma comissão, escolha quais vales serão descontados e informe o valor. Descontos parciais reduzem automaticamente o saldo restante.</p>${list.length?list.map(a=>{const used=advanceUsed(a.id),remaining=Math.max(0,a.amount-used);return `<article class="transfer ${a.voided?'voided':''}"><div><strong>${esc(a.description)}</strong><small>Pago em ${esc(a.date.split('-').reverse().join('/'))} · Valor original: ${money(a.amount/100)}</small><small>${a.voided?'Cancelado':remaining===0?'Descontado integralmente':used?'Desconto parcial':'Pendente'} · Já descontado: ${money(used/100)}</small></div><div class="transfer-value"><small>Saldo restante</small><strong>${money(a.voided?0:remaining/100)}</strong><div>${used?'<small>Vinculado a comissão quitada</small>':`<button data-edit-advance="${esc(a.id)}">Editar</button><button data-void-advance="${esc(a.id)}">${a.voided?'Restaurar':'Cancelar'}</button>`}</div></div></article>`;}).join(''):'<div class="empty"><h3>Nenhum vale registrado</h3><p>Registre o valor e a data do que você adiantou à pessoa.</p></div>'}`;}
function openAdvance(id=null){initAdvances();const a=state.advances.find(a=>a.id===id);if(a&&advanceUsed(id)){toast('Reabra a comissão vinculada antes de alterar este vale.');return;}const f=$('#advance-form');f.reset();f.elements.person.innerHTML=state.people.map(p=>`<option value="${esc(p.id)}">${esc(p.name)} · ${esc(p.role||'Prestador')}</option>`).join('');f.elements.person.value=a?.person||selected;advanceContext={id,person:selected};$('#advance-title').textContent=a?'Editar vale':'Registrar vale';f.elements.description.value=a?.description||'';f.elements.amount.value=a?formatCredit(a.amount):'';f.elements.date.value=a?.date||new Intl.DateTimeFormat('sv-SE',{timeZone:'America/Sao_Paulo',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());$('#advance-dialog').showModal();}
function validateAdvances(s){if(s.advances!==undefined){if(!Array.isArray(s.advances))throw Error('Vales inválidos');const ids=new Set();for(const a of s.advances){if(!a||typeof a.id!=='string'||ids.has(a.id)||!s.people.some(p=>p.id===a.person)||!validDate(a.date)||(a.month!==undefined&&!/^\d{4}-(0[1-9]|1[0-2])$/.test(a.month))||!Number.isSafeInteger(a.amount)||a.amount<=0||typeof a.description!=='string'||!a.description.trim()||typeof a.voided!=='boolean')throw Error('Vale inválido');ids.add(a.id);}}const used={};for(const [key,r] of Object.entries(s.records)){if(!r.settlement)continue;const x=r.settlement;if(!Number.isSafeInteger(x.gross)||x.gross<0||!Number.isSafeInteger(x.net)||x.net<0||!Array.isArray(x.deductions)||!(x.date===null||validDate(x.date)))throw Error('Quitação inválida');let total=0;for(const d of x.deductions){const a=(s.advances||[]).find(a=>a.id===d.id);if(!a||a.person!==key.slice(8)||a.voided||!Number.isSafeInteger(d.amount)||d.amount<=0||typeof d.description!=='string')throw Error('Desconto inválido');used[d.id]=(used[d.id]||0)+d.amount;if(used[d.id]>a.amount)throw Error('Desconto duplicado');total+=d.amount;}if(x.gross-total!==x.net)throw Error('Total inválido');}}
document.querySelector('#close-advance').onclick=()=>$('#advance-dialog').close();
document.querySelector('#advance-form').onsubmit=e=>{e.preventDefault();const f=e.target;if(!f.reportValidity()||!advanceContext)return;const a={id:advanceContext.id||crypto.randomUUID(),person:f.elements.person.value,description:f.elements.description.value.trim(),amount:parseCredit(f.elements.amount.value),date:f.elements.date.value,voided:false};if(!state.people.some(p=>p.id===a.person)||!a.description||!validDate(a.date)||!a.amount)return;const prior=state.advances.find(x=>x.id===a.id);if(prior&&advanceUsed(a.id)){toast('Este vale já foi descontado em uma comissão quitada.');return;}if(prior){Object.assign(prior,a);delete prior.month;}else state.advances.push(a);selected=a.person;tab='advances';save();render();$('#advance-dialog').close();toast('Vale registrado');};
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.id==='add-advance')openAdvance();if(b.dataset.editAdvance)openAdvance(b.dataset.editAdvance);if(b.dataset.voidAdvance){const a=state.advances.find(a=>a.id===b.dataset.voidAdvance);if(!a||advanceUsed(a.id))return;a.voided=!a.voided;save();render();}});
const legacyAdvanceMonth=document.querySelector('#advance-form [name="month"]');if(typeof legacyAdvanceMonth?.closest==='function'){legacyAdvanceMonth.closest('label')?.remove();const note=document.querySelector('#advance-form .hint');if(note)note.textContent='O vale ficará pendente até você escolher o valor do desconto ao quitar uma comissão.';}
